func newStopETA() unsafe.Pointer { return unsafe.Pointer(new(stopeta.StopETA)) }

func newNStopETA(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]stopeta.StopETA, n)))
}

func ptrStopETA(p unsafe.Pointer, c int32) any {
	r := (*stopeta.StopETA)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 4:
		return (*string)(unsafe.Pointer(&r.ShipmentMoveID))
	case 5:
		return (*string)(unsafe.Pointer(&r.StopID))
	case 6:
		return &r.MoveSequence
	case 7:
		return &r.StopSequence
	case 8:
		return &r.Arrived
	case 9:
		return &r.EstimatedArrival
	case 10:
		return &r.EstimatedDeparture
	case 11:
		return &r.WindowEnd
	case 12:
		return &r.SlackMinutes
	case 13:
		return (*string)(unsafe.Pointer(&r.Verdict))
	case 14:
		return (*string)(unsafe.Pointer(&r.Basis))
	case 15:
		return (*string)(unsafe.Pointer(&r.DriveMethod))
	case 16:
		return &r.MilesRemaining
	case 17:
		return &r.DriveMinutes
	case 18:
		return &r.RestMinutes
	case 19:
		return &r.InputAt
	case 20:
		return &r.InputStale
	case 21:
		return &r.ThresholdMinutes
	case 22:
		return &r.Reason
	case 23:
		return &r.ComputedAt
	}
	return nil
}

func valueStopETA(p unsafe.Pointer, c int32) any {
	r := (*stopeta.StopETA)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		return string(r.ShipmentMoveID)
	case 5:
		return string(r.StopID)
	case 6:
		return r.MoveSequence
	case 7:
		return r.StopSequence
	case 8:
		return r.Arrived
	case 9:
		if r.EstimatedArrival == nil {
			return nil
		}
		return *r.EstimatedArrival
	case 10:
		if r.EstimatedDeparture == nil {
			return nil
		}
		return *r.EstimatedDeparture
	case 11:
		if r.WindowEnd == nil {
			return nil
		}
		return *r.WindowEnd
	case 12:
		if r.SlackMinutes == nil {
			return nil
		}
		return *r.SlackMinutes
	case 13:
		return string(r.Verdict)
	case 14:
		return string(r.Basis)
	case 15:
		return string(r.DriveMethod)
	case 16:
		return r.MilesRemaining
	case 17:
		return r.DriveMinutes
	case 18:
		return r.RestMinutes
	case 19:
		if r.InputAt == nil {
			return nil
		}
		return *r.InputAt
	case 20:
		return r.InputStale
	case 21:
		return r.ThresholdMinutes
	case 22:
		if r.Reason == "" {
			return nil
		}
		return r.Reason
	case 23:
		return r.ComputedAt
	}
	return nil
}

